-- IHA core schema, ported from the Supabase migrations (packages/db/supabase/migrations).
--
-- Portability rules (this file must run unchanged on H2 in PostgreSQL mode and on PostgreSQL):
--   * ids are uuid, generated by the application (no gen_random_uuid()).
--   * text columns are unbounded varchar (H2 maps TEXT to CLOB).
--   * JSON payloads are stored as varchar holding JSON text.
--   * columns ending in _enc hold AES-GCM ciphertext (Base64) written by the API;
--     they replace the pgcrypto bytea columns of the old schema.
--   * updated_at is maintained by the application, not by triggers.
--   * row-level security does not exist here: access rules live in the service layer.

-- ─────────────────────────────────────────────────────────
-- Accounts (replaces Supabase auth.users)
-- ─────────────────────────────────────────────────────────
create table app_users (
  id                uuid                     primary key,
  email             varchar                  not null,
  password_hash     varchar                  not null,
  role              varchar                  not null,
  email_verified_at timestamp with time zone,
  created_at        timestamp with time zone not null default current_timestamp,
  constraint app_users_email_key unique (email),
  constraint app_users_role_check check (role in ('PATIENT', 'DOCTOR', 'HOSPITAL', 'LAWYER', 'ADMIN'))
);

create table email_verification_codes (
  id          uuid                     primary key,
  user_id     uuid                     not null references app_users (id) on delete cascade,
  code_hash   varchar                  not null,
  attempts    integer                  not null default 0,
  expires_at  timestamp with time zone not null,
  consumed_at timestamp with time zone,
  created_at  timestamp with time zone not null default current_timestamp
);

create index email_verification_codes_user_idx on email_verification_codes (user_id);

-- ─────────────────────────────────────────────────────────
-- Reference data
-- ─────────────────────────────────────────────────────────
create table specialties (
  id         uuid                     primary key,
  name       varchar                  not null,
  label_en   varchar                  not null,
  label_zh   varchar                  not null,
  is_active  boolean                  not null default true,
  sort_order integer                  not null default 0,
  created_at timestamp with time zone not null default current_timestamp,
  updated_at timestamp with time zone not null default current_timestamp,
  constraint specialties_name_key unique (name)
);

create table platform_fee_settings (
  id         uuid                     primary key,
  fee_key    varchar                  not null,
  amount_aud numeric(12, 2)           not null,
  updated_at timestamp with time zone not null default current_timestamp,
  constraint platform_fee_settings_fee_key_key unique (fee_key)
);

-- ─────────────────────────────────────────────────────────
-- Role profiles
-- ─────────────────────────────────────────────────────────
create table patients (
  id                                 uuid                     primary key,
  user_id                            uuid                     not null references app_users (id) on delete cascade,
  full_name_enc                      varchar                  not null,
  date_of_birth_enc                  varchar,
  phone_enc                          varchar,
  address_enc                        varchar,
  gender                             varchar,
  nationality                        varchar,
  country_of_residence               varchar,
  medical_history_enc                varchar,
  allergies_enc                      varchar,
  current_medications_enc            varchar,
  past_surgeries_enc                 varchar,
  emergency_contact_name_enc         varchar,
  emergency_contact_relationship_enc varchar,
  emergency_contact_phone_enc        varchar,
  avatar_url                         varchar,
  stripe_customer_id                 varchar,
  email_notifications_enabled        boolean                  not null default true,
  sms_notifications_enabled          boolean                  not null default false,
  is_deleted                         boolean                  not null default false,
  deleted_at                         timestamp with time zone,
  scheduled_delete_at                timestamp with time zone,
  created_at                         timestamp with time zone not null default current_timestamp,
  updated_at                         timestamp with time zone not null default current_timestamp,
  constraint patients_user_id_key unique (user_id)
);

create table hospitals (
  id                          uuid                     primary key,
  user_id                     uuid                     references app_users (id) on delete set null,
  name                        varchar                  not null,
  registration_type           varchar,
  registration_number_enc     varchar,
  license_number_enc          varchar,
  abn_number_enc              varchar,
  accreditation_body          varchar,
  address                     varchar,
  city                        varchar                  not null,
  country                     varchar                  not null,
  zip_code                    varchar,
  phone                       varchar,
  contact_email               varchar,
  bed_count                   integer,
  room_types                  varchar array            not null,
  specialties                 varchar array,
  certificates                varchar                  not null default '[]',
  status                      varchar                  not null default 'pending',
  rejection_reason            varchar,
  more_info_message           varchar,
  email_notifications_enabled boolean                  not null default true,
  sms_notifications_enabled   boolean                  not null default false,
  created_at                  timestamp with time zone not null default current_timestamp,
  constraint hospitals_user_id_key unique (user_id),
  constraint hospitals_status_check check (status in ('pending', 'approved', 'rejected', 'more_info_requested'))
);

create table lawyers (
  id                            uuid                     primary key,
  user_id                       uuid                     references app_users (id) on delete set null,
  lead_lawyer_id                uuid                     references lawyers (id) on delete set null,
  lawyer_type                   varchar                  not null,
  name                          varchar                  not null,
  registration_number_enc       varchar,
  abn_number_enc                varchar,
  immigration_law_certification varchar,
  address                       varchar,
  city                          varchar,
  zip_code                      varchar,
  contact_phone                 varchar,
  certificates                  varchar                  not null default '[]',
  status                        varchar                  not null default 'pending',
  rejection_reason              varchar,
  more_info_message             varchar,
  email_notifications_enabled   boolean                  not null default true,
  sms_notifications_enabled     boolean                  not null default false,
  created_at                    timestamp with time zone not null default current_timestamp,
  updated_at                    timestamp with time zone not null default current_timestamp,
  constraint lawyers_user_id_key unique (user_id),
  constraint lawyers_status_check check (status in ('pending', 'approved', 'rejected', 'more_info_requested')),
  constraint lawyers_type_check check (lawyer_type in ('individual', 'law_firm'))
);

create table doctors (
  id                           uuid                     primary key,
  user_id                      uuid                     references app_users (id) on delete set null,
  full_name                    varchar                  not null,
  date_of_birth_enc            varchar,
  license_number_enc           varchar,
  gender                       varchar,
  role                         varchar,
  department                   varchar,
  specialties                  varchar array,
  qualifications               varchar,
  years_experience             integer,
  languages_spoken             varchar array,
  bio                          varchar,
  photo_url                    varchar,
  contact_email                varchar,
  contact_phone                varchar,
  working_days                 varchar array            not null,
  availability_schedule        varchar                  not null default '{}',
  certificates                 varchar                  not null default '[]',
  status                       varchar                  not null default 'pending',
  rejection_reason             varchar,
  more_info_message            varchar,
  registration_fee_paid_at     timestamp with time zone,
  annual_fee_next_due_at       timestamp with time zone,
  annual_fee_reminder_sent_for date,
  email_notifications_enabled  boolean                  not null default true,
  sms_notifications_enabled    boolean                  not null default false,
  created_at                   timestamp with time zone not null default current_timestamp,
  constraint doctors_user_id_key unique (user_id),
  constraint doctors_status_check check (status in ('pending', 'approved', 'rejected', 'more_info_requested')),
  constraint doctors_role_check check (role is null or role in ('consultant', 'surgeon'))
);

create table doctor_hospital_affiliations (
  id          uuid                     primary key,
  doctor_id   uuid                     not null references doctors (id) on delete cascade,
  hospital_id uuid                     not null references hospitals (id) on delete cascade,
  created_at  timestamp with time zone not null default current_timestamp,
  constraint doctor_hospital_affiliations_key unique (doctor_id, hospital_id)
);

-- ─────────────────────────────────────────────────────────
-- Cases
-- ─────────────────────────────────────────────────────────
create sequence cases_reference_seq start with 1;

create table cases (
  id                             uuid                     primary key,
  patient_id                     uuid                     not null references patients (id) on delete cascade,
  reference_number               varchar                  not null,
  specialty                      varchar                  not null,
  specialty_other                varchar,
  description_enc                varchar                  not null,
  status                         varchar                  not null default 'case_submitted',
  need_travel_assistance         boolean                  not null default false,
  need_stay_booking_assistance   boolean                  not null default false,
  need_transportation_assistance boolean                  not null default false,
  created_at                     timestamp with time zone not null default current_timestamp,
  updated_at                     timestamp with time zone not null default current_timestamp,
  constraint cases_reference_number_key unique (reference_number),
  constraint cases_status_check check (status in (
    'case_submitted', 'under_review', 'doctor_assigned', 'evaluation',
    'treatment_plan', 'treatment_confirmed', 'payment_confirmed',
    'visa_documents_submitted', 'visa_processing', 'travel_ready',
    'visa_rejected', 'completed', 'closed'
  ))
);

create index cases_patient_idx on cases (patient_id);
create index cases_status_idx on cases (status);

create table case_documents (
  id                uuid                     primary key,
  patient_id        uuid                     not null references patients (id) on delete cascade,
  case_id           uuid                     references cases (id) on delete set null,
  document_category varchar                  not null default 'medical',
  document_type     varchar                  not null,
  file_name         varchar                  not null,
  file_path         varchar                  not null,
  file_size_bytes   bigint                   not null,
  mime_type         varchar                  not null,
  uploaded_at       timestamp with time zone not null default current_timestamp,
  constraint case_documents_type_check check (document_type in (
    'lab_report', 'mri_ct', 'xray', 'prescription', 'medical_history', 'other',
    'passport', 'passport_photograph', 'hospital_invitation', 'appointment_confirmation',
    'bank_statement', 'sponsorship_letter', 'employer_letter', 'companion_passport',
    'companion_proof_of_relationship'
  ))
);

create index case_documents_case_idx on case_documents (case_id);
create index case_documents_patient_idx on case_documents (patient_id);

-- ─────────────────────────────────────────────────────────
-- Patient ↔ coordinator chat
-- ─────────────────────────────────────────────────────────
create table chat_threads (
  id                  uuid                     primary key,
  patient_id          uuid                     not null references patients (id) on delete cascade,
  status              varchar                  not null default 'closed',
  opened_at           timestamp with time zone,
  closed_at           timestamp with time zone,
  reopen_reason       varchar,
  reopen_requested_at timestamp with time zone,
  created_at          timestamp with time zone not null default current_timestamp,
  updated_at          timestamp with time zone not null default current_timestamp,
  constraint chat_threads_patient_key unique (patient_id),
  constraint chat_threads_status_check check (status in ('open', 'closed'))
);

create table chat_messages (
  id          uuid                     primary key,
  thread_id   uuid                     not null references chat_threads (id) on delete cascade,
  sender_id   uuid                     not null references app_users (id) on delete cascade,
  sender_type varchar                  not null,
  body        varchar                  not null,
  read        boolean                  not null default false,
  created_at  timestamp with time zone not null default current_timestamp,
  constraint chat_messages_sender_type_check check (sender_type in ('patient', 'admin'))
);

create index chat_messages_thread_idx on chat_messages (thread_id);

-- ─────────────────────────────────────────────────────────
-- Doctor assignments and treatment plans
-- ─────────────────────────────────────────────────────────
create table doctor_case_assignments (
  id                    uuid                     primary key,
  case_id               uuid                     not null references cases (id) on delete cascade,
  doctor_id             uuid                     not null references doctors (id) on delete cascade,
  status                varchar                  not null default 'invited',
  decline_reason        varchar,
  invited_at            timestamp with time zone not null default current_timestamp,
  responded_at          timestamp with time zone,
  evaluation_started_at timestamp with time zone,
  plan_submitted_at     timestamp with time zone,
  constraint doctor_case_assignments_status_check check (status in ('invited', 'accepted', 'declined', 'withdrawn', 'cancelled'))
);

create index doctor_case_assignments_case_idx on doctor_case_assignments (case_id);
create index doctor_case_assignments_doctor_idx on doctor_case_assignments (doctor_id);

create table treatment_plans (
  id                           uuid                     primary key,
  case_id                      uuid                     not null references cases (id) on delete cascade,
  doctor_id                    uuid                     not null references doctors (id) on delete cascade,
  hospital_id                  uuid                     references hospitals (id) on delete set null,
  status                       varchar                  not null default 'draft',
  treatment_type               varchar,
  department                   varchar,
  room_category                varchar,
  treatment_duration_days      integer,
  treatment_start_date         date,
  treatment_end_date           date,
  diagnosis_enc                varchar,
  procedure_name_enc           varchar,
  technique_enc                varchar,
  description_enc              varchar,
  expected_outcome_enc         varchar,
  success_rate_enc             varchar,
  recovery_time_enc            varchar,
  estimated_length_of_stay_enc varchar,
  special_requirements_enc     varchar,
  patient_instructions_enc     varchar,
  aftercare_enc                varchar                  not null,
  cost_breakdown_enc           varchar                  not null,
  cost_notes_enc               varchar,
  doctor_fees_aud_enc          varchar,
  hospital_fees_aud_enc        varchar,
  submitted_at                 timestamp with time zone,
  created_at                   timestamp with time zone not null default current_timestamp,
  updated_at                   timestamp with time zone not null default current_timestamp,
  constraint treatment_plans_status_check check (status in (
    'draft', 'submitted_to_iha', 'iha_review_in_progress', 'iha_approved',
    'rejected_by_iha', 'presented_to_patient', 'patient_confirmed', 'not_selected'
  )),
  constraint treatment_plans_treatment_type_check check (
    treatment_type is null or treatment_type in ('medication_only', 'surgery', 'therapy')
  )
);

create index treatment_plans_case_idx on treatment_plans (case_id);

create table treatment_options (
  id                 uuid                     primary key,
  case_id            uuid                     not null references cases (id) on delete cascade,
  treatment_plan_id  uuid                     not null references treatment_plans (id) on delete cascade,
  mta_commission_aud numeric(12, 2)           not null default 0,
  is_selected        boolean                  not null default false,
  published_at       timestamp with time zone,
  created_at         timestamp with time zone not null default current_timestamp
);

create index treatment_options_case_idx on treatment_options (case_id);

create table treatment_plan_specialists (
  id                  uuid                     primary key,
  treatment_plan_id   uuid                     not null references treatment_plans (id) on delete cascade,
  specialist_type     varchar                  not null,
  specialist_name_enc varchar,
  cost_aud_enc        varchar                  not null,
  notes_enc           varchar,
  created_at          timestamp with time zone not null default current_timestamp,
  constraint treatment_plan_specialists_type_check check (specialist_type in (
    'anaesthetist', 'radiologist', 'pathologist', 'rehabilitation', 'other'
  ))
);

-- ─────────────────────────────────────────────────────────
-- Consultations
-- ─────────────────────────────────────────────────────────
create table consultation_requests (
  id                  uuid                     primary key,
  case_id             uuid                     not null references cases (id) on delete cascade,
  patient_id          uuid                     not null references patients (id) on delete cascade,
  treatment_option_id uuid                     not null references treatment_options (id) on delete cascade,
  selected_slot_id    uuid,
  status              varchar                  not null default 'requested',
  zoom_link           varchar,
  cancellation_reason varchar,
  requested_at        timestamp with time zone not null default current_timestamp,
  updated_at          timestamp with time zone not null default current_timestamp,
  constraint consultation_requests_status_check check (status in (
    'requested', 'slots_proposed', 'slot_selected', 'scheduled', 'cancelled'
  ))
);

create table consultation_slots (
  id                      uuid                     primary key,
  consultation_request_id uuid                     not null references consultation_requests (id) on delete cascade,
  slot_time               timestamp with time zone not null,
  slot_end_time           timestamp with time zone not null,
  created_at              timestamp with time zone not null default current_timestamp,
  constraint consultation_slots_end_after_start check (slot_end_time > slot_time)
);

alter table consultation_requests
  add constraint consultation_requests_selected_slot_fk
  foreign key (selected_slot_id) references consultation_slots (id) on delete set null;

-- ─────────────────────────────────────────────────────────
-- Payments
-- ─────────────────────────────────────────────────────────
create table payments (
  id                       uuid                     primary key,
  case_id                  uuid                     not null references cases (id) on delete cascade,
  patient_id               uuid                     not null references patients (id) on delete cascade,
  treatment_option_id      uuid                     references treatment_options (id) on delete set null,
  consultation_request_id  uuid                     references consultation_requests (id) on delete set null,
  payment_type             varchar                  not null default 'full_payment',
  amount_aud               numeric(12, 2)           not null,
  status                   varchar                  not null default 'pending',
  gateway                  varchar                  not null default 'stripe',
  gateway_reference        varchar,
  stripe_payment_intent_id varchar,
  invoice_path             varchar,
  paid_at                  timestamp with time zone,
  created_at               timestamp with time zone not null default current_timestamp,
  constraint payments_type_check check (payment_type in ('full_payment', 'consultation_fee')),
  constraint payments_status_check check (status in ('pending', 'completed', 'failed', 'refunded'))
);

create index payments_case_idx on payments (case_id);

create table payment_methods (
  id                       uuid                     primary key,
  user_id                  uuid                     not null references app_users (id) on delete cascade,
  stripe_payment_method_id varchar                  not null,
  brand                    varchar                  not null,
  last4                    varchar                  not null,
  exp_month                integer                  not null,
  exp_year                 integer                  not null,
  is_default               boolean                  not null default false,
  created_at               timestamp with time zone not null default current_timestamp
);

create table doctor_fee_payments (
  id                       uuid                     primary key,
  doctor_id                uuid                     not null references doctors (id) on delete cascade,
  fee_type                 varchar                  not null,
  amount_aud               numeric(12, 2)           not null,
  billing_period           varchar,
  status                   varchar                  not null default 'pending',
  gateway                  varchar                  not null default 'stripe',
  gateway_reference        varchar,
  stripe_payment_intent_id varchar,
  invoice_path             varchar,
  paid_at                  timestamp with time zone,
  created_at               timestamp with time zone not null default current_timestamp,
  constraint doctor_fee_payments_fee_type_check check (fee_type in ('registration', 'annual')),
  constraint doctor_fee_payments_status_check check (status in ('pending', 'completed', 'failed'))
);

-- ─────────────────────────────────────────────────────────
-- Visa
-- ─────────────────────────────────────────────────────────
create table visa_submissions (
  id                 uuid                     primary key,
  case_id            uuid                     not null references cases (id) on delete cascade,
  patient_id         uuid                     not null references patients (id) on delete cascade,
  assigned_lawyer_id uuid                     references lawyers (id) on delete set null,
  status             varchar                  not null default 'documents_submitted',
  form_data_enc      varchar,
  rejection_reason   varchar,
  created_at         timestamp with time zone not null default current_timestamp,
  updated_at         timestamp with time zone not null default current_timestamp,
  constraint visa_submissions_case_key unique (case_id),
  constraint visa_submissions_status_check check (status in (
    'not_started', 'documents_submitted', 'under_review', 'additional_docs_requested',
    'application_submitted', 'processing', 'approved', 'rejected'
  ))
);

create table visa_documents (
  id                  uuid                     primary key,
  patient_id          uuid                     not null references patients (id) on delete cascade,
  case_id             uuid                     references cases (id) on delete cascade,
  visa_submission_id  uuid                     references visa_submissions (id) on delete cascade,
  hospital_id         uuid                     references hospitals (id) on delete set null,
  category            varchar                  not null,
  source              varchar                  not null default 'patient_upload',
  requested_by_lawyer boolean                  not null default false,
  file_name           varchar                  not null,
  file_path           varchar                  not null,
  file_size_bytes     bigint,
  mime_type           varchar,
  sent_to_patient_at  timestamp with time zone,
  uploaded_at         timestamp with time zone not null default current_timestamp,
  constraint visa_documents_source_check check (source in ('patient_upload', 'hospital_generated', 'lawyer_issued')),
  constraint visa_documents_submission_or_case_check check (
    source = 'patient_upload' or visa_submission_id is not null or case_id is not null
  )
);

create index visa_documents_case_idx on visa_documents (case_id);

create table visa_document_requests (
  id            uuid                     primary key,
  case_id       uuid                     not null references cases (id) on delete cascade,
  lawyer_id     uuid                     not null references lawyers (id) on delete cascade,
  category      varchar                  not null,
  document_type varchar                  not null,
  instructions  varchar,
  created_at    timestamp with time zone not null default current_timestamp
);

create table visa_case_notes (
  id         uuid                     primary key,
  case_id    uuid                     not null references cases (id) on delete cascade,
  lawyer_id  uuid                     not null references lawyers (id) on delete cascade,
  body       varchar                  not null,
  created_at timestamp with time zone not null default current_timestamp
);

-- ─────────────────────────────────────────────────────────
-- Provider ↔ admin messages
-- ─────────────────────────────────────────────────────────
create table provider_message_threads (
  id                  uuid                     primary key,
  account_type        varchar                  not null,
  hospital_id         uuid                     references hospitals (id) on delete cascade,
  doctor_id           uuid                     references doctors (id) on delete cascade,
  lawyer_id           uuid                     references lawyers (id) on delete cascade,
  status              varchar                  not null default 'closed',
  opened_at           timestamp with time zone,
  closed_at           timestamp with time zone,
  reopen_reason       varchar,
  reopen_requested_at timestamp with time zone,
  created_at          timestamp with time zone not null default current_timestamp,
  updated_at          timestamp with time zone not null default current_timestamp,
  constraint provider_message_threads_account_type_check check (account_type in ('hospital', 'doctor', 'lawyer')),
  constraint provider_message_threads_status_check check (status in ('open', 'closed')),
  constraint provider_message_threads_account_shape_check check (
    (account_type = 'hospital' and hospital_id is not null and doctor_id is null and lawyer_id is null)
    or (account_type = 'doctor' and doctor_id is not null and hospital_id is null and lawyer_id is null)
    or (account_type = 'lawyer' and lawyer_id is not null and hospital_id is null and doctor_id is null)
  )
);

create table provider_messages (
  id          uuid                     primary key,
  thread_id   uuid                     not null references provider_message_threads (id) on delete cascade,
  sender_id   uuid                     not null references app_users (id) on delete cascade,
  sender_type varchar                  not null,
  body        varchar                  not null,
  read        boolean                  not null default false,
  created_at  timestamp with time zone not null default current_timestamp,
  constraint provider_messages_sender_type_check check (sender_type in ('hospital', 'doctor', 'lawyer', 'admin'))
);

-- ─────────────────────────────────────────────────────────
-- Notifications and audit
-- ─────────────────────────────────────────────────────────
create table notifications (
  id            uuid                     primary key,
  user_id       uuid                     not null references app_users (id) on delete cascade,
  case_id       uuid                     references cases (id) on delete cascade,
  assignment_id uuid                     references doctor_case_assignments (id) on delete cascade,
  type          varchar                  not null,
  title         varchar                  not null,
  message       varchar                  not null,
  read          boolean                  not null default false,
  created_at    timestamp with time zone not null default current_timestamp
);

create index notifications_user_idx on notifications (user_id, created_at);

create table audit_logs (
  id          uuid                     primary key,
  actor_id    uuid                     references app_users (id) on delete set null,
  actor_email varchar,
  app         varchar                  not null,
  action      varchar                  not null,
  entity_type varchar,
  entity_id   varchar,
  metadata    varchar                  not null default '{}',
  created_at  timestamp with time zone not null default current_timestamp
);

create index audit_logs_created_idx on audit_logs (created_at);
